'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var tryRequire = require( '@stdlib/utils/try-require' );
var toFloat32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

var round10f = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( round10f instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof round10f, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', opts, function test( t ) {
	var v = round10f( toFloat32( +0.0 ), 0 );
	t.strictEqual( isPositiveZero( v ), true, 'returns +0' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', opts, function test( t ) {
	var v = round10f( toFloat32( -0.0 ), 0 );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var v = round10f( NaN, 0 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', opts, function test( t ) {
	var v = round10f( PINF, 0 );
	t.strictEqual( v, PINF, 'returns +infinity' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', opts, function test( t ) {
	var v = round10f( NINF, 0 );
	t.strictEqual( v, NINF, 'returns -infinity' );
	t.end();
});

tape( 'the function rounds to the nearest integer when n = 0', opts, function test( t ) {
	t.strictEqual( round10f( 3.14, 0 ), 3.0, '3.14 -> 3' );
	t.strictEqual( round10f( 3.5, 0 ), 4.0, 'ties-to-even' );
	t.strictEqual( round10f( 2.5, 0 ), 2.0, 'ties-to-even' );
	t.strictEqual( round10f( -2.5, 0 ), -2.0, 'ties-to-even' );
	t.end();
});

tape( 'the function rounds to the nearest tenth when n = -1', opts, function test( t ) {
	t.strictEqual( round10f( 3.14, -1 ), toFloat32( 3.1 ), '3.14 -> 3.1' );
	t.strictEqual( round10f( 3.15, -1 ), toFloat32( 3.2 ), '3.15 -> 3.2' );
	t.end();
});

tape( 'the function rounds to the nearest hundredth when n = -2', opts, function test( t ) {
	t.strictEqual( round10f( 1.234, -2 ), toFloat32( 1.23 ), '1.234 -> 1.23' );
	t.strictEqual( round10f( 1.235, -2 ), toFloat32( 1.24 ), 'ties handled' );
	t.end();
});

tape( 'the function rounds to the nearest 10 when n = 1', opts, function test( t ) {
	t.strictEqual( round10f( 17.2, 1 ), 20.0, '17.2 -> 20' );
	t.strictEqual( round10f( 14.9, 1 ), 10.0, '14.9 -> 10' );
	t.end();
});

tape( 'the function rounds to the nearest 100 when n = 2', opts, function test( t ) {
	t.strictEqual( round10f( 249.0, 2 ), 200.0, '249 -> 200' );
	t.strictEqual( round10f( 250.0, 2 ), 300.0, 'ties-to-even' );
	t.end();
});

tape( 'the function preserves signed zeros after rounding', opts, function test( t ) {
	t.strictEqual( isPositiveZero( round10f( +0.04, -1 ) ), true, '+0 stays +0' );
	t.strictEqual( isNegativeZero( round10f( -0.04, -1 ) ), true, '-0 stays -0' );
	t.end();
});
